import{d as s,C as m,o,c as l,j as i,a,E as e,a3 as y}from"./chunks/framework.D4-ViStF.js";const z=JSON.parse('{"title":"天隐子","description":"唐代司马承祯所序的修真入门短篇，八篇加序与后序口诀，以易简为宗，渐门五阶，由斋戒至神解。","frontmatter":{"title":"天隐子","description":"唐代司马承祯所序的修真入门短篇，八篇加序与后序口诀，以易简为宗，渐门五阶，由斋戒至神解。","category":"guide","aliases":["天隐子","tianyinzi","天隐子八篇","司马承祯"],"source":["天隐子","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/tianyinzi.md","filePath":"daoism/daoist-classics/tianyinzi.md","lastUpdated":1789714390000}'),h={name:"daoism/daoist-classics/tianyinzi.md"},c=s({...h,setup(d){const r=[{id:"wumei",term:"寤寐",pinyin:["wù","mèi"],meaning:"寤，醒；寐，睡。昼夜寤寐，即醒与睡两种状态。"},{id:"xin zhu",term:"心主",pinyin:["xīn zhǔ"],meaning:"心的主宰。序中以阴阳神灵为心之主，即神明所居。"},{id:"bo yang",term:"伯阳",pinyin:["bó yáng"],meaning:"老子李耳，字伯阳。此处指老子之道。"},{id:"zhuang sou",term:"庄叟",pinyin:["zhuāng sǒu"],meaning:"庄子。叟为老者之称。序谓天隐子之遗照与庄子齐同。"},{id:"yi zhao",term:"遗照",pinyin:["yí zhào"],meaning:"遗，遗落、放下；照，观照。遗照指放下外照而内守，与坐忘相呼应。"},{id:"yao cu",term:"夭促",pinyin:["yāo cù"],meaning:"夭折短促。惜乎世人夭促真寿，谓世人自损其本可长之寿。"},{id:"shuai",term:"率",pinyin:["shuài"],meaning:"大率，大抵、大概。「人之身，大率不远乎神仙之道矣」，谓人的身体大抵与神仙之道相去不远。"},{id:"dai",term:"殆",pinyin:["dài"],meaning:"几乎、大概。「殆非人间所能力学也」，谓大约不是人间靠力学所能达到的。"},{id:"qi",term:"契",pinyin:["qì"],meaning:"契合、相合。「归根，契于伯阳」，谓其归本之旨与老子（伯阳）相合。可参《道德经》「夫物芸芸，各复归其根」。"},{id:"chengzhen",term:"承祯",pinyin:["chéng","zhēn"],meaning:"司马承祯（647—735），唐代道士，字子微，号白云子，上清派宗师。著《坐忘论》，并为《天隐子》作序及后序口诀。"},{id:"bing",term:"禀",pinyin:["bǐng"],meaning:"禀受、承受。禀得灵气即生来承受了灵明之气。"},{id:"zhai shen",term:"宅神",pinyin:["zhái shén"],meaning:"宅，居住、安顿。宅神于内，谓把神明安顿在身内。"},{id:"lun wu",term:"沦污",pinyin:["lún wū"],meaning:"沉沦玷污。勿为世俗所沦污，谓不要被世俗拖累染污。"},{id:"ning zhi",term:"凝滞",pinyin:["níng zhì"],meaning:"凝结滞留、受困不通。邪见所凝滞，谓被偏邪之见困住。"},{id:"laoyi",term:"劳佚",pinyin:["láo","yì"],meaning:"佚同「逸」。劳佚即过劳与过逸，是与饮饱并列的「气之邪」。"},{id:"zhise",term:"滞塞",pinyin:["zhì","sè"],meaning:"停滞阻塞。「学无滞塞」，谓学习不会滞碍不通。"},{id:"xiejian",term:"邪见",pinyin:["xié","jiàn"],meaning:"不正之见、偏邪的见解。「勿为邪见所凝滞」，谓不要被偏邪之见困住。"},{id:"yinbao",term:"饮饱",pinyin:["yǐn","bǎo"],meaning:"饮食的饥饱失度。列于「气之邪」八者之中，谓饮食不节亦可成气之邪。"},{id:"yi jian",term:"易简",pinyin:["yì jiǎn"],meaning:"平易简约。语出《易·系辞》，此篇借以立宗：道不繁难，开目即是。"},{id:"fan qiao",term:"繁巧",pinyin:["fán qiǎo"],meaning:"繁复巧饰。无假繁巧，谓不借助复杂巧妙的说辞。"},{id:"zhi ren",term:"至人",pinyin:["zhì rén"],meaning:"修养至极之人。至人无为，谓其不假造作而自成。"},{id:"qi gui",term:"奇诡",pinyin:["qí guǐ"],meaning:"奇异诡怪。苟言涉奇诡，谓若立论涉于怪诞，便已离本。"},{id:"zhi mi",term:"执迷",pinyin:["zhí mí"],meaning:"固执沉迷。使人执迷、无所归本，即失其根本。"},{id:"zhidaobufan",term:"至道不繁",pinyin:["zhì","dào","bù","fán"],meaning:"至高的道理并不繁琐。与《道德经》「大道甚夷，而民好径」相通。"},{id:"zhirenwuwei",term:"至人无为",pinyin:["zhì","rén","wú","wéi"],meaning:"修养至极之人不假造作。可参《庄子·逍遥游》「至人无己」与[《道德经》](/daoism/dao-de-jing/)「道常无为而无不为」。"},{id:"gou",term:"苟",pinyin:["gǒu"],meaning:"如果、假如。「苟言涉奇诡」，谓若所言涉及奇诡。"},{id:"she",term:"涉",pinyin:["shè"],meaning:"涉及、牵涉。「言涉奇诡」即言谈牵涉奇诡之说。"},{id:"fan",term:"反",pinyin:["fǎn"],meaning:"反而、反倒。「反为仙所卷」，谓反而被「仙」这件事卷进去。"},{id:"juanzhe",term:"卷者",pinyin:["juǎn","zhě"],meaning:"被卷入、被裹挟的人。「反为仙所卷者有矣」，谓世人学仙反被求仙之念所卷。一说「卷」通「惑」。"},{id:"dun wu",term:"顿悟",pinyin:["dùn wù"],meaning:"一念豁然而悟。此篇明言不能顿悟，故须渐修——这是天隐子立「渐门」的理由。"},{id:"jian men",term:"渐门",pinyin:["jiàn mén"],meaning:"渐次而入的门径。取《易》渐卦之义，成五阶：斋戒、安处、存想、坐忘、神解。"},{id:"zao shen xu xin",term:"澡身虚心",pinyin:["zǎo shēn xū xīn"],meaning:"斋戒之解：洗净形身、虚其心。非仅指沐浴吃素。"},{id:"shou xin fu xing",term:"收心复性",pinyin:["shōu xīn fù xìng"],meaning:"存想之解：把散逸的心收回来，复归本然之性。"},{id:"yi xing wang wo",term:"遗形忘我",pinyin:["yí xíng wàng wǒ"],meaning:"坐忘之解：放下形骸、忘掉自我。"},{id:"wan fa tong shen",term:"万法通神",pinyin:["wàn fǎ tōng shén"],meaning:"神解之解：于一切法皆能通达而归于神。"},{id:"shu ru",term:"蔬茹",pinyin:["shū rú"],meaning:"菜食。斋戒非仅指吃素，此篇正为此辩。"},{id:"tiao zhong",term:"调中",pinyin:["tiáo zhōng"],meaning:"调和中气、调和脾胃。食勿令饱即调中。"},{id:"chang wai",term:"畅外",pinyin:["chàng wài"],meaning:"使外部气血通畅。摩擦皮肤熨去冷气，即畅外之法。"},{id:"xing hai",term:"形骸",pinyin:["xíng hái"],meaning:"形体躯壳。调理形骸之法，谓先从身体下手。"},{id:"xiu liang fu qi",term:"休粮服气",pinyin:["xiū liáng fú qì"],meaning:"停食谷物、服食气。此篇明言其为道家权宜，非永绝食粒。"},{id:"quan yi",term:"权宜",pinyin:["quán yí"],meaning:"一时方便的变通之法，非究竟之常道。"},{id:"yun",term:"熨",pinyin:["yùn"],meaning:"以温热之物按压、贴敷。「温热熨去冷气」，即以摩擦生热熨散寒气。"},{id:"sui yu",term:"邃宇",pinyin:["suì yǔ"],meaning:"深邃的屋宇。华堂邃宇，指华丽深广的居所。"},{id:"yin",term:"裀",pinyin:["yīn"],meaning:"褥垫。重裀，多层垫褥，谓过求舒适。"},{id:"he",term:"阖",pinyin:["hé"],meaning:"关闭。遇风即阖，谓有风则闭窗。"},{id:"juan lian",term:"捲帘",pinyin:["juǎn lián"],meaning:"卷起帘子。太暗则捲帘以通外耀，与「太明即下帘」相对。"},{id:"gong ji",term:"攻肌",pinyin:["gōng jī"],meaning:"侵袭肌肤。元阳之攻肌，谓阳气过盛外侵。"},{id:"qin hua",term:"侵滑",pinyin:["qīn huá"],meaning:"浸淫滑腻而入。淫阴之侵滑，谓阴湿之气渗入。"},{id:"huatangsuiyu",term:"华堂邃宇",pinyin:["huá","táng","suì","yǔ"],meaning:"华丽的殿堂、深邃的屋宇。此篇以「非华堂邃宇」破「居处愈华贵愈好」之见。"},{id:"chongyinguangta",term:"重裀广榻",pinyin:["chóng","yīn","guǎng","tà"],meaning:"重裀，多层褥垫；广榻，宽大的床榻。谓过求舒适，非安处之本。"},{id:"bei",term:"卑",pinyin:["bēi"],meaning:"低矮、卑下。「屋无卑」，谓房屋不要过低矮闭塞。"},{id:"cun xiang",term:"存想",pinyin:["cún xiǎng"],meaning:"存，存守我之神；想，想见我之身。与「坐忘」为一对工夫。"},{id:"ying ying fu guang",term:"营营浮光",pinyin:["yíng yíng fú guāng"],meaning:"营营，往来不定；浮光，浮在表面的目光。喻心神外逐不息。"},{id:"fu zhao",term:"复照",pinyin:["fù zhào"],meaning:"回光返照。未尝复照，谓从不肯把目光收回来看自己。"},{id:"gui gen fu ming",term:"归根复命",pinyin:["guī gēn fù mìng"],meaning:"语出《老子》。归根曰静，静曰复命——回到根本，复其本命。"},{id:"cheng xing cun cun",term:"成性存存",pinyin:["chéng xìng cún cún"],meaning:"语出《易·系辞》。成就其性，存之又存，故为众妙之门。"},{id:"naihe",term:"柰何",pinyin:["nài","hé"],meaning:"即「奈何」，如何、怎么。「柰」为「奈」的古写（原文如此，未改）。"},{id:"xingdoumin",term:"形都泯",pinyin:["xíng","dōu","mǐn"],meaning:"形体全然淡化、不再显著。与《庄子·大宗师》「堕肢体，黜聪明，离形去知，同于大通」相承。"},{id:"zuo wang",term:"坐忘",pinyin:["zuò wàng"],meaning:"因存想而得、因存想而忘。坐非端坐之坐，而是「行道而不见其行」。"},{id:"min",term:"泯",pinyin:["mǐn"],meaning:"消失、灭尽。形都泯，谓连形体都忘却了。"},{id:"ming",term:"暝",pinyin:["míng"],meaning:"闭目。天隐子暝而不视，以不视代答。"},{id:"xin jie",term:"信解",pinyin:["xìn jiě"],meaning:"斋戒所得：无信心则不能解。"},{id:"ding jie",term:"定解",pinyin:["dìng jiě"],meaning:"安处所得：无定心则不能解。"},{id:"xian jie",term:"闲解",pinyin:["xián jiě"],meaning:"存想所得：无闲心则不能解。"},{id:"hui jie",term:"慧解",pinyin:["huì jiě"],meaning:"坐忘所得：无慧心则不能解。四解具足，方称神解。"},{id:"san cai",term:"三才",pinyin:["sān cái"],meaning:"天、地、人。兼三才而言谓之易，谓易道通贯三才。"},{id:"zhen ru",term:"真如",pinyin:["zhēn rú"],meaning:"佛家语，谓真实如常之性。此篇以之与易、道德并举。"},{id:"bu duo zhu shu",term:"不堕诸数",pinyin:["bù duò zhū shù"],meaning:"不落于一切数量分别之中，即超乎计量。"},{id:"shishi",term:"释氏",pinyin:["shì","shì"],meaning:"佛教。释，指释迦牟尼，故以「释氏」称佛家。"},{id:"fahua",term:"法华",pinyin:["fǎ","huá"],meaning:"《妙法莲华经》，简称《法华经》。主张会三归一、众生皆可成佛，故曰「皆一性」。"},{id:"lengqie",term:"楞伽",pinyin:["léng","qié"],meaning:"《楞伽经》。讲如来藏与万法唯识，为禅宗早期所重。"},{id:"niepan",term:"涅盘",pinyin:["niè","pán"],meaning:"梵语音译，指烦恼寂灭、不生不灭之境。通行作「涅槃」，原文作「涅盘」。"},{id:"yuanjuejing",term:"圆觉经",pinyin:["yuán","jué","jīng"],meaning:"《大方广圆觉修多罗了义经》，讲众生本具圆觉妙心。原文引其「不堕诸数」之说。"},{id:"rong wei",term:"荣卫",pinyin:["róng wèi"],meaning:"中医谓血为荣、气为卫。荣卫血脉，寤行于外、寐行于内。"},{id:"dao yin",term:"导引",pinyin:["dǎo yǐn"],meaning:"导气令和、引体令柔，古代的吐纳与体操之术。"},{id:"hua chi",term:"华池",pinyin:["huá chí"],meaning:"口中。以舌搅华池，即舌在口中搅动生津。"},{id:"shu yan",term:"漱咽",pinyin:["shù yàn"],meaning:"漱，漱口；咽，吞下。指漱津而咽之。"},{id:"ni wan",term:"泥丸",pinyin:["ní wán"],meaning:"道家谓脑为泥丸宫，在头顶。气上彻泥丸，即上达于顶。"},{id:"ji lu",term:"脊膂",pinyin:["jǐ lǚ"],meaning:"脊骨。膂即脊梁骨。"},{id:"wo gu",term:"握固",pinyin:["wò gù"],meaning:"握拳固气之法，拇指压于四指之内。"},{id:"ming qi",term:"冥契",pinyin:["míng qì"],meaning:"暗相契合。与天地真气冥契同运，谓与天地呼吸相合。"},{id:"xing hou",term:"形候",pinyin:["xíng hòu"],meaning:"显现的征候。辨识气来形候，即辨明真气到来的迹象。"},{id:"xiezuo",term:"偕作",pinyin:["xié","zuò"],meaning:"一同兴起、俱起。「适与天地之气偕作」，谓人身之气与天地之气同时发动。"},{id:"yingshi",term:"应时",pinyin:["yìng","shí"],meaning:"与时节相应。「夜半之候，是其应时」，谓夜半正是相合之时。"},{id:"xishi",term:"袭仕",pinyin:["xí","shì"],meaning:"承袭官职、入仕为官。「予后既袭仕，遂尔中辍」，谓入仕之后即中断了修习。"},{id:"zhongchuo",term:"中辍",pinyin:["zhōng","chuò"],meaning:"中途停止。「遂尔中辍」，谓修习就此半途而止。"},{id:"dadedingwei",term:"大德丁未",pinyin:["dà","dé"],meaning:"元成宗年号。大德丁未，即大德十一年（1307）。"},{id:"qi_2",term:"炁",pinyin:["qì"],meaning:"道家专用字，指先天元气，与后天呼吸之「气」相区别。唐岩起题「运自己之炁」，即运自家先天之气，与天地之气偕作。"},{id:"qin mu",term:"锓木",pinyin:["qǐn mù"],meaning:"锓，雕刻。锓木即刻版印书。王伦谓「谨锓木以传」，即刻板流传此书。"},{id:"cun san shou yi",term:"存三守一",pinyin:["cún sān shǒu yī"],meaning:"道家修养术语，谓存守三一。王伦以此概括此书的要旨。"},{id:"xieziran",term:"谢自然",pinyin:["xiè","zì","rán"],meaning:"唐代女道士。仙传载其白日飞升，为唐代著名的成道传说人物。"},{id:"simaziwei",term:"司马子微",pinyin:["sī","mǎ","zǐ","wēi"],meaning:"即司马承祯，字子微。跋语以「子微」称之。"},{id:"chicheng",term:"赤城",pinyin:["chì","chéng"],meaning:"天台山赤城山，司马承祯修道之地。苏轼词「人间自有赤城居士」即指此。"},{id:"jiangque",term:"绛阙",pinyin:["jiàng","què"],meaning:"绛色宫阙，指天上仙阙。「名在绛阙」，谓其名已列入仙籍。"},{id:"cunyi",term:"礻豆",pinyin:["存疑"],meaning:"疑为传抄或识读讹字，字书未见，或为「祼」（guàn，祭祀）之类误拆。原文「虽未能礻豆枯骨」，大意近「脱胎换骨」。姑存原文，待考。"},{id:"ji",term:"觊",pinyin:["jì"],meaning:"希望、希冀。「所觊免致沦没幻身」，谓所希望的是不使此身沉沦毁坏。"},{id:"lunmohuanshen",term:"沦没幻身",pinyin:["lún","mò","huàn","shēn"],meaning:"沦没，沉沦埋没；幻身，谓此身如幻无常。「所觊免致沦没幻身」，即不愿白白荒废此幻化之身。"},{id:"jiading",term:"嘉定",pinyin:["jiā","dìng"],meaning:"南宋宁宗年号。嘉定己卯，即嘉定十二年（1219）。"}];return(u,n)=>{const p=m("DaoReadingPrelude"),t=m("DaoTextReading"),g=m("DaoKeywordCards");return o(),l("div",null,[n[0]||(n[0]=i("h1",{id:"天隐子",tabindex:"-1"},[a("天隐子 "),i("a",{class:"header-anchor",href:"#天隐子","aria-label":'Permalink to "天隐子"'},"​")],-1)),e(p,{title:"先看天隐如何以简入门",summary:"天隐子比坐忘论更短、更简、更贴近日常。全书八篇，前有司马承祯序，后有后序口诀。它以「易简」为总纲，将修真之路拆为渐门五阶——斋戒、安处、存想、坐忘、神解——不是从空中谈玄，而是从日常生活能下手的地方开始。",points:[{label:"先立纲",text:"「易简」不是偷懒，而是顺应天地本然的路径。"},{label:"再拆阶",text:"渐门五阶从饮食起居到心念专注，层层递进。"},{label:"后归本",text:"终点「神解」不是神通，而是心与道自然合一。"}],hint:"若是第一次读天隐子，建议先抓住「易简」二字，再看渐门五阶的递进关系。全篇按序、八篇、后序口诀分节，可逐篇慢读。"}),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("h3",{id:"xu",tabindex:"-1"},[a("天隐子序 "),i("a",{class:"header-anchor",href:"#xu","aria-label":'Permalink to "天隐子序 {#xu}"'},"​")],-1)),e(t,{glossary:r,paragraphs:["神仙之道，以长生为本，长生之要，以养气为根。夫气受之于天地，和之于阴阳，阴阳神灵，谓之心主，昼夜寤寐，谓之魂魄。是故人之身，大率不远乎神仙之道矣。天隐子，吾不知其何许人，著书八篇，包括秘妙，殆非人间所能力学者也。观夫修炼形气，养和心灵，归根，契于伯阳，遗照齐于庄叟，长生久视，无出是书。承祯服习道风，惜乎世人夭促真寿，思欲传之同志，使简易而行，信哉！自伯阳以来，惟天隐子而已矣。","唐司马承祯谨序。"]}),n[3]||(n[3]=i("h3",{id:"pian-1",tabindex:"-1"},[a("神仙一 "),i("a",{class:"header-anchor",href:"#pian-1","aria-label":'Permalink to "神仙一 {#pian-1}"'},"​")],-1)),e(t,{glossary:r,paragraphs:["人，生时禀得灵气，精明通悟，学无滞塞，则谓之神；宅神于内，遗照于外，自然异于俗人，则谓之神仙。故神仙亦人也。在于修我灵气，勿为世俗所沦污，遂我自然，勿为邪见所凝滞，则成功矣。","喜、怒、哀、乐、爱、恶、欲七者，情之邪也；风、寒、暑、湿、饮饱、劳佚八者，气之邪也。去此邪，则道近矣。"]}),n[4]||(n[4]=i("h3",{id:"pian-2",tabindex:"-1"},[a("易简二 "),i("a",{class:"header-anchor",href:"#pian-2","aria-label":'Permalink to "易简二 {#pian-2}"'},"​")],-1)),e(t,{glossary:r,paragraphs:["易曰：天地之道，易简者，何也？","天隐子曰：天地在我首之上，足之下，开目尽见，无假繁巧而言，故曰易简。易简者，神仙之德也。经曰：至道不繁，至人无为。","然则以何道求之？曰：无求不能知，无道不能成。","凡学神仙，先知易简，苟言涉奇诡，适足使人执迷，无所归本，此非吾学也。世人学仙，反为仙所卷者有矣；学气，反为气所病者，有矣。"]}),n[5]||(n[5]=i("h3",{id:"pian-3",tabindex:"-1"},[a("渐门三 "),i("a",{class:"header-anchor",href:"#pian-3","aria-label":'Permalink to "渐门三 {#pian-3}"'},"​")],-1)),e(t,{glossary:r,paragraphs:["易有渐卦，道有渐门。人之修真达性，不能顿悟，必须渐而进之，安而行之，故设渐门，观我所入，则道可见矣。","渐有五门：一曰斋戒，二曰安处，三曰存想，四曰坐忘，五曰神解。","何谓斋戒？曰：澡身虚心。","何谓安处？曰：深居静室。","何谓存想？曰：收心复性。","何谓坐忘？曰：遗形忘我。","何谓神解？曰：万法通神。","是故习此渐门者，了一则渐次至二，了二则渐次至三，了三则渐次至四，了四则渐次至五，神仙成矣。"]}),n[6]||(n[6]=i("h3",{id:"pian-4",tabindex:"-1"},[a("斋戒四 "),i("a",{class:"header-anchor",href:"#pian-4","aria-label":'Permalink to "斋戒四 {#pian-4}"'},"​")],-1)),e(t,{glossary:r,paragraphs:["斋戒者，非蔬茹饮食而已；澡身者，非汤浴去垢而已。盖其法在乎节食调中，摩擦畅外者也。","夫人禀五行之气，而食五行之物，实自胞胎有形，已呼吸精血，岂可去食而求长生？但世人不知休粮服气，是道家之权宜，非永绝食粒之谓也。","故食之有斋戒者，斋乃洁净之务，戒乃节约之称。有饥即食，食勿令饱，此所谓调中也。","百味未成熟勿食，五味太多勿食，腐败闭气之物勿食，此皆宜戒也。","手常摩擦皮肤，温热熨去冷气，此所谓畅外也。久坐、久立、久劳、久役，皆宜戒也。","此是调理形骸之法，形坚则气全，是以斋戒为渐门之首矣。"]}),n[7]||(n[7]=i("h3",{id:"pian-5",tabindex:"-1"},[a("安处五 "),i("a",{class:"header-anchor",href:"#pian-5","aria-label":'Permalink to "安处五 {#pian-5}"'},"​")],-1)),e(t,{glossary:r,paragraphs:["何谓安处？曰：非华堂邃宇，重裀广榻之谓也。在乎南向而坐，东首而寝，阴阳适中，明暗相半。","屋无高，高则阳盛而明多；屋无卑，卑则阴盛而暗多。故明多则伤魄，暗多则伤魂。人之魂阳而魄阴，苟伤明暗，则疾病生焉。","此所谓居处之室，尚使之然，况天地之气，有元阳之攻肌，淫阴之侵滑，岂不慎哉？","修养之渐，倘不法此，非安处之道。术曰：作所居室，四边皆窗户，遇风即阖，风息即开。吾所居座，前帘后屏，太明即下帘以和其内映，太暗则捲帘以通其外耀。内以安心，外以安目，心目皆安，则身安矣。","明暗尚然，况太多事虑，太多情欲，岂能安其内外哉？故学道以安处为次。"]}),n[8]||(n[8]=i("h3",{id:"pian-6",tabindex:"-1"},[a("存想六 "),i("a",{class:"header-anchor",href:"#pian-6","aria-label":'Permalink to "存想六 {#pian-6}"'},"​")],-1)),e(t,{glossary:r,paragraphs:["存谓存我之神，想谓想我之身。闭目即见自己之目，收心即见自己之心，心与目皆不离我身，不伤我神，则存想之渐也。","凡人目终日视他人，故心亦逐外走；终日接他事，故目亦逐外瞻，营营浮光，未尝复照，柰何不病且夭邪？","是以归根曰静，静曰复命，成性存存，众妙之门。此存想之渐，学道之根。"]}),n[9]||(n[9]=i("h3",{id:"pian-7",tabindex:"-1"},[a("坐忘七 "),i("a",{class:"header-anchor",href:"#pian-7","aria-label":'Permalink to "坐忘七 {#pian-7}"'},"​")],-1)),e(t,{glossary:r,paragraphs:["坐忘者，因存想而得也，因存想而忘也。","行道而不见其行，非坐之义乎？有见而不行其见，非忘之义乎？","何谓不行？曰：心不动故。何谓不见？曰：形都泯故。","故天隐子暝而不视。"]}),n[10]||(n[10]=i("h3",{id:"pian-8",tabindex:"-1"},[a("神解八 "),i("a",{class:"header-anchor",href:"#pian-8","aria-label":'Permalink to "神解八 {#pian-8}"'},"​")],-1)),e(t,{glossary:r,paragraphs:["斋戒谓之信解，言无信心，则不能解。","安处谓之定解，言无定心，则不能解。","存想谓之闲解，言无闲心，则不能解。","坐忘谓之慧解，言无慧心，则不能解。","信、定、闲、慧四门通神，谓之神解。","故神之为义，不行而至，不疾而速，阴阳变通，天地长久。","兼三才而言谓之易，系辞云：易穷则变，变则通，通则久。齐万物而言，谓之道德，老子道经、德经是也。本一性而言，谓之真如，释氏法华、楞伽、涅盘皆一性。入于真如，归于无为。圆觉经云：佛身有为，至于无为佛化身，不堕诸数皆一性。","故天隐子生乎易中，死乎易中，动因万物，静因万物，邪由一性，真由一性，是以生死动静邪真，皆以神而解之。","在人谓之人仙，在天曰天仙，在地曰地仙，在水曰水仙，能通变之曰神仙。故神仙之道有五，其渐学之门则一焉，谓五渐终，同归于神矣。"]}),n[11]||(n[11]=i("h3",{id:"shu-hou",tabindex:"-1"},[a("书天隐子后 "),i("a",{class:"header-anchor",href:"#shu-hou","aria-label":'Permalink to "书天隐子后 {#shu-hou}"'},"​")],-1)),e(t,{glossary:r,paragraphs:["昔谢自然欲过海求师蓬莱，至海上，或谓自然曰：蓬莱隔弱水三十万里，不可到。天台有司马子微，身居赤城，名在绛阙，可往从之。自然乃还，受道于子微，白日仙去。东坡水龙吟词云：古来云海茫茫，蓬山绛阙知何处？人间自有赤城居士。龙蟠凤举，清静无为，坐忘遗照。八篇奇语。观此，则此书八篇，当是子微所著，而序乃云天隐子，不知何许人，意者不欲自显其名邪？","绍兴壬午，从事郎、知台州黄岩县、主管学事劝农公事胡琏跋。","尝本青：天地之大德曰生，人之大宝曰道。夫道者本乎清净，其要在乎存三守一，其理甚易知，甚易习，然非庸人之可探，惟造道者能之。伦夙慕斯门，虽未能礻豆枯骨，所觊免致沦没幻身。偶访同志，得一帙曰天隐子。捧读三复，实乃修真之枢要也。唐司马子微得之于王屋山石刻，遂为之序，后又附之口诀，伦自有生以来，未之获知也。其蕴奥机妙，历历垂示。伦自揣才识浅陋，未敢遽以微言称议，欲得与众共之，谨锓木以传焉。","时嘉定己卯岁戊辰月，天赦日，琅琊王伦谨书。","予读天隐子后序，所谓冬至子时，一阳气始来，运自己之炁，与之偕作，此神仙至妙之术。予曾遇人授以斯说，夜半之候，是其应时，门日不差。予后既袭仕，遂尔中辍，即金丹之弦气也。","大德丁未十一月三十日，子真子唐岩起题。","天隐子八篇，不知何人所作，唐司马承祯为之序。承祯字子微，尝著坐忘论。此书言长生久视之法，与之相表里，岂天隐子即承祯欤？洪兴祖讳承祯，得天隐子之学，岂或别有考欤？","金华宋濂辩。"]}),n[12]||(n[12]=i("h3",{id:"koujue",tabindex:"-1"},[a("后序口诀 "),i("a",{class:"header-anchor",href:"#koujue","aria-label":'Permalink to "后序口诀 {#koujue}"'},"​")],-1)),e(t,{glossary:r,paragraphs:["承祯诵天隐子之书三年，恍然有所悟，乃依此五门，渐渐进习。又三年，觉身心之间而名利之淡矣。又三年，天隐子出焉，授之以口诀，其要在存想篇，归根复命，成性众妙者是也。","夫人之根本，由丹田而生，能复则长命，故曰归根复命。夫人之灵识，本乎理性，性通则妙万物而不穷，故曰成性众妙。然而呼吸由气而活，故我有吐纳之诀；津液由水藏而生，故我有漱咽之诀；思虑由心识而动，故我有存想之诀。","人身荣卫血脉，寤即行于外，寐即行于内，寤寐内外，相养和平，然后每日自夜半子时至日中午时，先平卧，舒展四肢，次起身导引，喘息均定，乃先叩当门齿小鸣，后叩犬齿大鸣，以两手摩面及眼，身觉暖畅，复端坐盘足，以舌搅华池，候津液生而漱之，默记其数，数及三百而一咽之。凡咽津，候呼定而咽，咽毕而吸。如此则吸气与津顺下丹田也。但子后午前，食消心空之时，频频漱咽，无论遍数，意尽则止。","凡五日为一候，当焚香于静室中，存想自身从首至足，又自足至丹田，上脊膂，入于泥丸，想其气如云，直贯泥丸。想毕，复漱咽，乃以两手掩两耳，搭其脑，如鼓声三七，下伸两足，端足俯首，极力直颈，两手握固，又于两胁下按腰胯骨傍，乃左右耸两肩甲，闭息顷刻，候气盈面赤即止。凡行七遍，气从脊膂，上彻泥丸。此修养之大纲也。","然更有要妙，在乎与天地真气，冥契同运，能识气来之时，又辨气息之所。若是，则与天地齐其长久，谓之神仙矣。","法起冬至夜子时，一阳气始来，或迟或早，先须辨识气来形候，才觉气来，则运自己之气，适与天地之气偕作。次日复候此气而消息之，此是神仙至妙至精之术，人罕达之。倘三百六十日内，运气适合真气三两次，则自觉身体清和，异于常时矣。况久久习之，积累冥契，则神仙之道不难至矣。","唐司马承祯撰。后序口诀终。"]}),n[13]||(n[13]=i("h2",{id:"【原典层】字词释义",tabindex:"-1"},[a("【原典层】字词释义 "),i("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n[14]||(n[14]=i("blockquote",null,[i("p",null,"随文逐篇增补，非一次完工。")],-1)),e(g,{title:"序 · 字词",items:[{term:"寤寐",pinyin:["wù","mèi"],meaning:"寤，醒；寐，睡。昼夜寤寐，即醒与睡两种状态。"},{term:"心主",pinyin:["xīn zhǔ"],meaning:"心的主宰。序中以阴阳神灵为心之主，即神明所居。"},{term:"伯阳",pinyin:["bó yáng"],meaning:"老子李耳，字伯阳。此处指老子之道。"},{term:"庄叟",pinyin:["zhuāng sǒu"],meaning:"庄子。叟为老者之称。序谓天隐子之遗照与庄子齐同。"},{term:"遗照",pinyin:["yí zhào"],meaning:"遗，遗落、放下；照，观照。遗照指放下外照而内守，与坐忘相呼应。"},{term:"夭促",pinyin:["yāo cù"],meaning:"夭折短促。惜乎世人夭促真寿，谓世人自损其本可长之寿。"},{term:"率",pinyin:["shuài"],meaning:"大率，大抵、大概。「人之身，大率不远乎神仙之道矣」，谓人的身体大抵与神仙之道相去不远。"},{term:"殆",pinyin:["dài"],meaning:"几乎、大概。「殆非人间所能力学也」，谓大约不是人间靠力学所能达到的。"},{term:"契",pinyin:["qì"],meaning:"契合、相合。「归根，契于伯阳」，谓其归本之旨与老子（伯阳）相合。可参《道德经》「夫物芸芸，各复归其根」。"},{term:"承祯",pinyin:["chéng","zhēn"],meaning:"司马承祯（647—735），唐代道士，字子微，号白云子，上清派宗师。著《坐忘论》，并为《天隐子》作序及后序口诀。"}]}),e(g,{title:"神仙一 · 字词",items:[{term:"禀",pinyin:["bǐng"],meaning:"禀受、承受。禀得灵气即生来承受了灵明之气。"},{term:"宅神",pinyin:["zhái shén"],meaning:"宅，居住、安顿。宅神于内，谓把神明安顿在身内。"},{term:"沦污",pinyin:["lún wū"],meaning:"沉沦玷污。勿为世俗所沦污，谓不要被世俗拖累染污。"},{term:"凝滞",pinyin:["níng zhì"],meaning:"凝结滞留、受困不通。邪见所凝滞，谓被偏邪之见困住。"},{term:"劳佚",pinyin:["láo","yì"],meaning:"佚同「逸」。劳佚即过劳与过逸，是与饮饱并列的「气之邪」。"},{term:"滞塞",pinyin:["zhì","sè"],meaning:"停滞阻塞。「学无滞塞」，谓学习不会滞碍不通。"},{term:"邪见",pinyin:["xié","jiàn"],meaning:"不正之见、偏邪的见解。「勿为邪见所凝滞」，谓不要被偏邪之见困住。"},{term:"饮饱",pinyin:["yǐn","bǎo"],meaning:"饮食的饥饱失度。列于「气之邪」八者之中，谓饮食不节亦可成气之邪。"}]}),e(g,{title:"易简二 · 字词",items:[{term:"易简",pinyin:["yì jiǎn"],meaning:"平易简约。语出《易·系辞》，此篇借以立宗：道不繁难，开目即是。"},{term:"繁巧",pinyin:["fán qiǎo"],meaning:"繁复巧饰。无假繁巧，谓不借助复杂巧妙的说辞。"},{term:"至人",pinyin:["zhì rén"],meaning:"修养至极之人。至人无为，谓其不假造作而自成。"},{term:"奇诡",pinyin:["qí guǐ"],meaning:"奇异诡怪。苟言涉奇诡，谓若立论涉于怪诞，便已离本。"},{term:"执迷",pinyin:["zhí mí"],meaning:"固执沉迷。使人执迷、无所归本，即失其根本。"},{term:"至道不繁",pinyin:["zhì","dào","bù","fán"],meaning:"至高的道理并不繁琐。与《道德经》「大道甚夷，而民好径」相通。"},{term:"至人无为",pinyin:["zhì","rén","wú","wéi"],meaning:"修养至极之人不假造作。可参《庄子·逍遥游》「至人无己」与[《道德经》](/daoism/dao-de-jing/)「道常无为而无不为」。"},{term:"苟",pinyin:["gǒu"],meaning:"如果、假如。「苟言涉奇诡」，谓若所言涉及奇诡。"},{term:"涉",pinyin:["shè"],meaning:"涉及、牵涉。「言涉奇诡」即言谈牵涉奇诡之说。"},{term:"反",pinyin:["fǎn"],meaning:"反而、反倒。「反为仙所卷」，谓反而被「仙」这件事卷进去。"},{term:"卷者",pinyin:["juǎn","zhě"],meaning:"被卷入、被裹挟的人。「反为仙所卷者有矣」，谓世人学仙反被求仙之念所卷。一说「卷」通「惑」。"}]}),e(g,{title:"渐门三 · 字词",items:[{term:"顿悟",pinyin:["dùn wù"],meaning:"一念豁然而悟。此篇明言不能顿悟，故须渐修——这是天隐子立「渐门」的理由。"},{term:"渐门",pinyin:["jiàn mén"],meaning:"渐次而入的门径。取《易》渐卦之义，成五阶：斋戒、安处、存想、坐忘、神解。"},{term:"澡身虚心",pinyin:["zǎo shēn xū xīn"],meaning:"斋戒之解：洗净形身、虚其心。非仅指沐浴吃素。"},{term:"收心复性",pinyin:["shōu xīn fù xìng"],meaning:"存想之解：把散逸的心收回来，复归本然之性。"},{term:"遗形忘我",pinyin:["yí xíng wàng wǒ"],meaning:"坐忘之解：放下形骸、忘掉自我。"},{term:"万法通神",pinyin:["wàn fǎ tōng shén"],meaning:"神解之解：于一切法皆能通达而归于神。"}]}),e(g,{title:"斋戒四 · 字词",items:[{term:"蔬茹",pinyin:["shū rú"],meaning:"菜食。斋戒非仅指吃素，此篇正为此辩。"},{term:"调中",pinyin:["tiáo zhōng"],meaning:"调和中气、调和脾胃。食勿令饱即调中。"},{term:"畅外",pinyin:["chàng wài"],meaning:"使外部气血通畅。摩擦皮肤熨去冷气，即畅外之法。"},{term:"形骸",pinyin:["xíng hái"],meaning:"形体躯壳。调理形骸之法，谓先从身体下手。"},{term:"休粮服气",pinyin:["xiū liáng fú qì"],meaning:"停食谷物、服食气。此篇明言其为道家权宜，非永绝食粒。"},{term:"权宜",pinyin:["quán yí"],meaning:"一时方便的变通之法，非究竟之常道。"},{term:"熨",pinyin:["yùn"],meaning:"以温热之物按压、贴敷。「温热熨去冷气」，即以摩擦生热熨散寒气。"},{term:"禀",pinyin:["bǐng"],meaning:"禀受。此篇谓人禀五行之气而生，与【神仙一】「禀得灵气」同字而偏重不同。"}]}),e(g,{title:"安处五 · 字词",items:[{term:"邃宇",pinyin:["suì yǔ"],meaning:"深邃的屋宇。华堂邃宇，指华丽深广的居所。"},{term:"裀",pinyin:["yīn"],meaning:"褥垫。重裀，多层垫褥，谓过求舒适。"},{term:"阖",pinyin:["hé"],meaning:"关闭。遇风即阖，谓有风则闭窗。"},{term:"捲帘",pinyin:["juǎn lián"],meaning:"卷起帘子。太暗则捲帘以通外耀，与「太明即下帘」相对。"},{term:"攻肌",pinyin:["gōng jī"],meaning:"侵袭肌肤。元阳之攻肌，谓阳气过盛外侵。"},{term:"侵滑",pinyin:["qīn huá"],meaning:"浸淫滑腻而入。淫阴之侵滑，谓阴湿之气渗入。"},{term:"华堂邃宇",pinyin:["huá","táng","suì","yǔ"],meaning:"华丽的殿堂、深邃的屋宇。此篇以「非华堂邃宇」破「居处愈华贵愈好」之见。"},{term:"重裀广榻",pinyin:["chóng","yīn","guǎng","tà"],meaning:"重裀，多层褥垫；广榻，宽大的床榻。谓过求舒适，非安处之本。"},{term:"卑",pinyin:["bēi"],meaning:"低矮、卑下。「屋无卑」，谓房屋不要过低矮闭塞。"}]}),e(g,{title:"存想六 · 字词",items:[{term:"存想",pinyin:["cún xiǎng"],meaning:"存，存守我之神；想，想见我之身。与「坐忘」为一对工夫。"},{term:"营营浮光",pinyin:["yíng yíng fú guāng"],meaning:"营营，往来不定；浮光，浮在表面的目光。喻心神外逐不息。"},{term:"复照",pinyin:["fù zhào"],meaning:"回光返照。未尝复照，谓从不肯把目光收回来看自己。"},{term:"归根复命",pinyin:["guī gēn fù mìng"],meaning:"语出《老子》。归根曰静，静曰复命——回到根本，复其本命。"},{term:"成性存存",pinyin:["chéng xìng cún cún"],meaning:"语出《易·系辞》。成就其性，存之又存，故为众妙之门。"},{term:"柰何",pinyin:["nài","hé"],meaning:"即「奈何」，如何、怎么。「柰」为「奈」的古写（原文如此，未改）。"},{term:"形都泯",pinyin:["xíng","dōu","mǐn"],meaning:"形体全然淡化、不再显著。与《庄子·大宗师》「堕肢体，黜聪明，离形去知，同于大通」相承。"}]}),e(g,{title:"坐忘七 · 字词",items:[{term:"坐忘",pinyin:["zuò wàng"],meaning:"因存想而得、因存想而忘。坐非端坐之坐，而是「行道而不见其行」。"},{term:"泯",pinyin:["mǐn"],meaning:"消失、灭尽。形都泯，谓连形体都忘却了。"},{term:"暝",pinyin:["míng"],meaning:"闭目。天隐子暝而不视，以不视代答。"}]}),e(g,{title:"神解八 · 字词",items:[{term:"信解",pinyin:["xìn jiě"],meaning:"斋戒所得：无信心则不能解。"},{term:"定解",pinyin:["dìng jiě"],meaning:"安处所得：无定心则不能解。"},{term:"闲解",pinyin:["xián jiě"],meaning:"存想所得：无闲心则不能解。"},{term:"慧解",pinyin:["huì jiě"],meaning:"坐忘所得：无慧心则不能解。四解具足，方称神解。"},{term:"三才",pinyin:["sān cái"],meaning:"天、地、人。兼三才而言谓之易，谓易道通贯三才。"},{term:"真如",pinyin:["zhēn rú"],meaning:"佛家语，谓真实如常之性。此篇以之与易、道德并举。"},{term:"不堕诸数",pinyin:["bù duò zhū shù"],meaning:"不落于一切数量分别之中，即超乎计量。"},{term:"五仙",pinyin:["wǔ xiān"],meaning:"人仙、天仙、地仙、水仙、神仙。其渐学之门则一，即渐门五阶。"},{term:"释氏",pinyin:["shì","shì"],meaning:"佛教。释，指释迦牟尼，故以「释氏」称佛家。"},{term:"法华",pinyin:["fǎ","huá"],meaning:"《妙法莲华经》，简称《法华经》。主张会三归一、众生皆可成佛，故曰「皆一性」。"},{term:"楞伽",pinyin:["léng","qié"],meaning:"《楞伽经》。讲如来藏与万法唯识，为禅宗早期所重。"},{term:"涅盘",pinyin:["niè","pán"],meaning:"梵语音译，指烦恼寂灭、不生不灭之境。通行作「涅槃」，原文作「涅盘」。"},{term:"圆觉经",pinyin:["yuán","jué","jīng"],meaning:"《大方广圆觉修多罗了义经》，讲众生本具圆觉妙心。原文引其「不堕诸数」之说。"}]}),e(g,{title:"后序口诀 · 字词",items:[{term:"荣卫",pinyin:["róng wèi"],meaning:"中医谓血为荣、气为卫。荣卫血脉，寤行于外、寐行于内。"},{term:"导引",pinyin:["dǎo yǐn"],meaning:"导气令和、引体令柔，古代的吐纳与体操之术。"},{term:"华池",pinyin:["huá chí"],meaning:"口中。以舌搅华池，即舌在口中搅动生津。"},{term:"漱咽",pinyin:["shù yàn"],meaning:"漱，漱口；咽，吞下。指漱津而咽之。"},{term:"泥丸",pinyin:["ní wán"],meaning:"道家谓脑为泥丸宫，在头顶。气上彻泥丸，即上达于顶。"},{term:"脊膂",pinyin:["jǐ lǚ"],meaning:"脊骨。膂即脊梁骨。"},{term:"握固",pinyin:["wò gù"],meaning:"握拳固气之法，拇指压于四指之内。"},{term:"冥契",pinyin:["míng qì"],meaning:"暗相契合。与天地真气冥契同运，谓与天地呼吸相合。"},{term:"形候",pinyin:["xíng hòu"],meaning:"显现的征候。辨识气来形候，即辨明真气到来的迹象。"},{term:"偕作",pinyin:["xié","zuò"],meaning:"一同兴起、俱起。「适与天地之气偕作」，谓人身之气与天地之气同时发动。"},{term:"应时",pinyin:["yìng","shí"],meaning:"与时节相应。「夜半之候，是其应时」，谓夜半正是相合之时。"},{term:"袭仕",pinyin:["xí","shì"],meaning:"承袭官职、入仕为官。「予后既袭仕，遂尔中辍」，谓入仕之后即中断了修习。"},{term:"中辍",pinyin:["zhōng","chuò"],meaning:"中途停止。「遂尔中辍」，谓修习就此半途而止。"},{term:"大德丁未",pinyin:["dà","dé","dīng","wèi"],meaning:"元成宗年号大德；大德丁未，即大德十一年（1307）。唐岩起题记之纪年。"}]}),e(g,{title:"书天隐子后 · 字词",items:[{term:"炁",pinyin:["qì"],meaning:"道家专用字，指先天元气，与后天呼吸之「气」相区别。唐岩起题「运自己之炁」，即运自家先天之气，与天地之气偕作。"},{term:"锓木",pinyin:["qǐn mù"],meaning:"锓，雕刻。锓木即刻版印书。王伦谓「谨锓木以传」，即刻板流传此书。"},{term:"存三守一",pinyin:["cún sān shǒu yī"],meaning:"道家修养术语，谓存守三一。王伦以此概括此书的要旨。"},{term:"谢自然",pinyin:["xiè","zì","rán"],meaning:"唐代女道士。仙传载其白日飞升，为唐代著名的成道传说人物。"},{term:"司马子微",pinyin:["sī","mǎ","zǐ","wēi"],meaning:"即司马承祯，字子微。跋语以「子微」称之。"},{term:"赤城",pinyin:["chì","chéng"],meaning:"天台山赤城山，司马承祯修道之地。苏轼词「人间自有赤城居士」即指此。"},{term:"绛阙",pinyin:["jiàng","què"],meaning:"绛色宫阙，指天上仙阙。「名在绛阙」，谓其名已列入仙籍。"},{term:"礻豆",pinyin:["存疑"],meaning:"疑为传抄或识读讹字，字书未见，或为「祼」（guàn，祭祀）之类误拆。原文「虽未能礻豆枯骨」，大意近「脱胎换骨」。姑存原文，待考。"},{term:"觊",pinyin:["jì"],meaning:"希望、希冀。「所觊免致沦没幻身」，谓所希望的是不使此身沉沦毁坏。"},{term:"沦没幻身",pinyin:["lún","mò","huàn","shēn"],meaning:"沦没，沉沦埋没；幻身，谓此身如幻无常。「所觊免致沦没幻身」，即不愿白白荒废此幻化之身。"},{term:"嘉定",pinyin:["jiā","dìng"],meaning:"南宋宁宗年号。嘉定己卯，即嘉定十二年（1219）。"}]}),n[15]||(n[15]=y('<h2 id="【解读层】导读" tabindex="-1">【解读层】导读 <a class="header-anchor" href="#【解读层】导读" aria-label="Permalink to &quot;【解读层】导读&quot;">​</a></h2><h3 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to &quot;象&quot;">​</a></h3><p>天隐子以一「渐」字为象。不是顿悟，不是跳跃，而是像登台阶般，一步一步走上去。斋戒调理身体，安处安置环境，存想收摄心神，坐忘放下执取，神解自然到。这五阶就像从打扫屋子开始，到最终安住于心——每一步都接得上，每一步都是下一步的根基。</p><h3 id="理" tabindex="-1">理 <a class="header-anchor" href="#理" aria-label="Permalink to &quot;理&quot;">​</a></h3><p>「易简」是全书总纲。天地在我首之上、足之下，开目尽见，不假繁巧——修行不是越复杂越高明，真正的路子往往是简单、直接、不绕弯的。司马承祯借易传之理，把修行从「奇诡怪诞」的想象中拉回来，落到了「有饥即食，食勿令饱」这样日常可做的功夫上。这与《道德经》「大道甚夷，而民好径」遥相呼应。</p><p>八篇的次序也有讲究：先立「神仙亦人也」（一），再破奇诡而归易简（二），然后才设渐门五阶（三至八）——先摆正见地，再谈工夫。</p><h3 id="用" tabindex="-1">用 <a class="header-anchor" href="#用" aria-label="Permalink to &quot;用&quot;">​</a></h3><p>天隐子最适合当「修行的日常清单」来用。斋戒一节，不是让人严格持素，而是问：饮食有没有过度？生活有没有节制？安处一节，不是让人换大房子，而是问：自己所在之处，是否有益于身心安定？存想一节，可以先从最简单的做——闭上眼，把注意力从外面收回来片刻。坐忘不急求，日常里能偶尔「忘掉」执念、焦虑、得失，就已经在门内了。</p><p>后序口诀把一路落到了具体的时辰与动作上：子后午前、漱咽咽津、焚香存想、七日七遍。不急照做，先知道「古人是怎么练的」也有用。</p><h3 id="我的理解" tabindex="-1">我的理解 <a class="header-anchor" href="#我的理解" aria-label="Permalink to &quot;我的理解&quot;">​</a></h3><p>天隐子最打动我的，是它<strong>不故弄玄虚</strong>。整本书没有一处奇诡的说法，讲的是「饿了就吃、别吃太饱」「窗户该关就关、该开就开」「别久坐久站」——这些朴素到几乎不像「修行」的提醒，反而比任何玄谈都更让人信服。它说「至道不繁」，而它自己就是这样做的。</p><p><strong>「形坚则气全」</strong> 这个次序也让我服气：斋戒排在渐门第一，不是从静坐、观想开始，而是从吃饭睡觉开始。作为一个每天对着屏幕的人，我读到这里有点惭愧——想要头脑清明、专注持久，却常年久坐、饮食随意。天隐子等于提前把这层道理说明白了：身体是地基，地基不稳，上面那些「心念的功夫」都是空的。</p><p><strong>「目终日视他人，故心亦逐外走」</strong> 这句我读了两遍。一千多年前写下的话，放在今天更像是写给我们：屏幕、消息、任务，无时无刻不在把「目」和「心」往外拽，难怪「营营浮光，未尝复照」。而它给的药方却极简——闭眼，把「看」收回来，看自己。</p><p><strong>「渐」</strong> 是我这一年体会最深的一个字。它明说「不能顿悟」「必须渐而进之」——没有哪次是「突然会了」，有的只是积累到某处、忽然贯通；所谓顿悟的那个瞬间，前面站着的都是渐修。这一点，跟学一门技术、读一部经典，其实是一回事。</p><p>读到「五渐终，同归于神矣」，我的感受是：天隐子并没有要求谁立刻去做什么惊天动地的功夫。它只是提醒——那些本来就知道、却一直没做到的日常，才是入口。</p><h2 id="【解读层】逐篇导读" tabindex="-1">【解读层】逐篇导读 <a class="header-anchor" href="#【解读层】逐篇导读" aria-label="Permalink to &quot;【解读层】逐篇导读&quot;">​</a></h2><blockquote><p>随逐篇细读增补，一篇一篇往下走。</p><p>相关篇目可对照阅读：<a href="/Dao/daoism/zhuang-zi/chapter-06">《庄子·大宗师》</a>（坐忘之说）、<a href="/Dao/daoism/zhuang-zi/chapter-01">《庄子·逍遥游》</a>（至人无己）、<a href="/Dao/daoism/dao-de-jing/">《道德经》</a>、<a href="/Dao/daoism/daoist-classics/zuowang-lun/">《坐忘论》</a>、<a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">《系辞上传》</a>。</p></blockquote><h3 id="神仙一-·-导读" tabindex="-1">神仙一 · 导读 <a class="header-anchor" href="#神仙一-·-导读" aria-label="Permalink to &quot;神仙一 · 导读&quot;">​</a></h3><p>这是全书开篇，也是总纲。序里已先点出「神仙亦人也」的基调，【神仙】篇要把它讲清楚：什么是「神」、什么是「神仙」、二者的差别在哪、如何才能成为神仙。</p><p><strong>三层结构</strong></p><ol><li>先下定义——什么是「神」，什么是「神仙」；</li><li>给出结论——「神仙亦人也」，关键在「修我灵气」；</li><li>指明障碍——情之邪、气之邪，去邪则近道。</li></ol><p><strong>逐句</strong></p><ul><li><p><strong>「人，生时禀得灵气，精明通悟，学无滞塞，则谓之神。」</strong> 给「神」下了一个极朴素、不带任何神秘色彩的定义：人生时禀受灵气，故头脑清明、通达领悟，学什么都不会遇到堵塞——这种状态就称为「神」。可见天隐子讲的「神」不是超自然的神灵，而是人自身心智清明无碍的状态。</p></li><li><p><strong>「宅神于内，遗照于外，自然异于俗人，则谓之神仙。」</strong> 在「神」的基础上说「神仙」：把这份清明安顿在内心（宅神于内），它又自然向外流露（遗照于外），整个人便自然而然与世俗常人不同。「神」是内在的功夫与境界，「神仙」是这份内在境界自然外显后所呈现的生命状态——并非另修出一个脱离肉身的仙体。</p></li><li><p><strong>「故神仙亦人也。」</strong> 全篇（甚至全书）最重要的一句论断。它打破了「神仙是脱离人身、超越人间、须靠丹药符咒等外力才能达到的特殊存在」这一误解——神仙就是人，只是把内在的「神」修养到通透清明、自然外显的程度。这与序文「人之身，大率不远乎神仙之道矣」遥相呼应：神仙之道并不遥远，就蕴藏在每个普通人的身心之中。</p></li><li><p><strong>「在于修我灵气，勿为世俗所沦污，遂我自然，勿为邪见所凝滞，则成功矣。」</strong> 两组对照：修我灵气 ←→ 勿为世俗所沦污（灵气本自有，怕被「污」）；遂我自然 ←→ 勿为邪见所凝滞（自然本可顺，怕被「滞」）。修行不是从外面添加什么神奇之物，而是护住、恢复本有的灵气与自然天性——与<a href="/Dao/daoism/dao-de-jing/">《道德经》</a>「见素抱朴」「复归其真」是同一路数：不外求，而内守。</p></li><li><p><strong>「喜、怒、哀、乐、爱、恶、欲七者，情之邪也；风、寒、暑、湿、饮饱、劳佚八者，气之邪也。去此邪，则道近矣。」</strong> 点出「污」与「滞」的来源：七情属「心」，八气属「身／境」。八气中前四项风寒暑湿是外在天气环境，后四项饮饱劳佚是自身饮食起居的失当。这一分也预告了后文的展开方向——七情之邪对应【存想】【坐忘】的收心，八气之邪对应【斋戒】【安处】的节食调中与阴阳适中。</p></li></ul><p><strong>多想一层</strong></p><ul><li><strong>「神」与「神仙」是「因」与「果」。</strong> 神是因——内在心智清明通悟的修养功夫；神仙是果——功夫修到位后自然显现、异于常人的生命状态。若一心只求「成为神仙」这个结果，却不下「修我灵气」的内在功夫，便是舍本逐末。</li><li><strong>七情八邪，不是要人绝情避世。</strong> 喜怒哀乐本是人之常情，风寒暑湿饮饱劳佚也是生活中不可避免的部分——它们本身不是问题，问题在于是否过度、失当，是否扰乱、污染、凝滞了本该清明自然的心与气。这与【斋戒】篇「饥即食，食勿令饱」是同一思路：不是禁绝，而是节制、适度。</li><li><strong>「俗人」与「神仙」之间没有一道不可逾越的鸿沟。</strong> 「自然异于俗人」讲的是<strong>修养程度</strong>的不同，紧接着「故神仙亦人也」讲的正是<strong>本质相同</strong>。差别的关键只在是否「修我灵气」「遂我自然」、是否去除了七情八邪的污染与凝滞——门槛不在玄妙莫测处，而在当下就可以着手的事：少一点情绪的过度耗损，多一点起居饮食的节制。</li></ul><p><strong>小结</strong></p><p>人生本有灵气（禀赋）→ 灵气清明即「神」（内在功夫）→ 神安于内、自然显于外即「神仙」（外显状态）→ 神仙亦人也（本质无异，只是修养程度不同）→ 修行的关键：修灵气、遂自然 → 修行的障碍：七情之邪（心）、八气之邪（身／境）→ 去邪，则道近矣。 这一篇篇幅不长，却已把全书的世界观（神仙亦人）、方法论（修灵气、遂自然）与问题意识（七情八邪）都交代清楚，是名副其实的开篇总纲。</p><h3 id="易简二-·-导读" tabindex="-1">易简二 · 导读 <a class="header-anchor" href="#易简二-·-导读" aria-label="Permalink to &quot;易简二 · 导读&quot;">​</a></h3><p>这一篇分量很重——它是全书方法论的「总开关」，后面【渐门】篇的整套修行体系都建立在它之上。如果说【神仙】篇回答「什么是神仙、为什么神仙亦人也」，这一篇回答的是：修行这条路，该走一条什么样的路？答案很干脆：易简之路。</p><p><strong>逐句</strong></p><ul><li><p><strong>「易曰：天地之道，易简者，何也？」</strong> 借《易经·系辞》起头，自己发问。《系辞》原作「乾以易知，坤以简能……易简而天下之理得矣」，天隐子浓缩成一句，然后自问：为什么说天地之道是「易简」的？这是典型的问答式写法——先引经立论，再自己解释。</p></li><li><p><strong>「天隐子曰：天地在我首之上，足之下，开目尽见，无假繁巧而言，故曰易简。」</strong> 回答极为直白，几乎带点「抬杠」意味：天在头顶、地在脚下，这有什么复杂的？睁开眼就全看见了，用不着靠繁复巧妙的言辞去解释。他不讲阴阳五行、天地生成之类的玄理，反而用最朴素的日常经验（抬头见天、低头见地）来印证「天地之道」并不神秘——连回答「什么是易简」时，用的都是最不绕弯的方式，这本身就是一种示范。</p></li><li><p><strong>「易简者，神仙之德也。经曰：至道不繁，至人无为。」</strong> 把「易简」提到很高的位置——它不只是天地的属性，更是「神仙之德」：真正修到神仙境界的人，所展现的品性正是「易简」二字。「至道不繁，至人无为」与《道德经》「道常无为而无不为」「损之又损，以至于无为」一脉相承。此处与【神仙】篇呼应：神仙亦人，关键在修灵气、遂自然；易简者，神仙之德——两者共同指向「真正的境界，外显出来是自然而简单，而不是繁复而刻意」。</p></li><li><p><strong>「然则以何道求之？曰：无求不能知，无道不能成。」</strong> 这句略显吊诡，值得细品。字面意思是：若不主动去「求」（探求、体认），不可能「知」这个道理；若没有正确的方法路径（「道」在此可指方法），也不可能「成」。换言之，「易简」不是说什么都不做、坐等天上掉下来——道理虽简单，仍需要「求」与「道」，才能「知」而后「成」。这是给「易简」划边界，免得被误解成「不用下功夫」。</p></li><li><p><strong>「凡学神仙，先知易简，苟言涉奇诡，适足使人执迷，无所归本，此非吾学也。」</strong> 全篇最重要的方法论宣言。学神仙之道，先要明白「易简」这个原则；若所言涉及奇特、诡异、玄怪莫测，后果是「使人执迷、无所归本」——这不是天隐子所主张的学问。可看作他对当时及后世道教修炼中大量符咒、法术、炼丹、奇门异法的明确划界。</p></li><li><p><strong>「世人学仙，反为仙所卷者有矣；学气，反为气所病者，有矣。」</strong> 举两个反面案例印证上句：有人想学成仙，反被「仙」这件事本身卷进去、迷失了自己（执着于成仙的念头或某种玄妙境界，反被套住）；有人想学养气，反因练气不当养出病来（用力过猛、方法不对、执着于气感体验而伤身）。方法不对，或心态执迷，都会适得其反。</p></li></ul><p><strong>多想一层</strong></p><ul><li><strong>「易简」不等于「简单粗暴」，而是「不假繁巧」。</strong> 它强调的不是随便、简陋、不用花心思，而是不必靠繁复巧饰的言辞去包装、去神秘化本来清楚明白的道理。道理本身可以很深，表达与体认的方式却可以直接、朴素——是「返璞归真」，不是降低标准。</li><li><strong>「无求不能知，无道不能成」提醒：易简不等于不劳而获。</strong> 在「速成」「捷径」「一招搞定」话术泛滥的环境里，很容易把「简单」误解成「不用花力气」。天隐子的「易简」恰恰相反：方法上不绕弯路、不故弄玄虚，但依然需要「求」与「道」，才能真正「知」「成」——这条路仍要一步步走，只是不绕远。</li><li><strong>「苟言涉奇诡」在今天依然有现实意义。</strong> 讲得越玄乎、越神秘，越容易让人「执迷」「无所归本」。面对各种「速成秘法」「神奇技巧」「玄学包装」，保持一份清醒：真正扎实、能落地的方法，往往是朴素、清楚、说得明白的，而不是故意讲得云里雾里、让人似懂非懂却心生崇拜的。</li></ul><p><strong>小结</strong></p><p>天地之道——易简（睁眼可见，无需繁巧言辞）→ 易简＝神仙之德（至道不繁，至人无为）→ 但易简 ≠ 不劳而获（无求不能知，无道不能成）→ 所以学神仙先立「易简」这个原则 → 排除项：凡涉奇诡怪诞之说，皆非此学（执迷、无所归本）→ 反面案例：学仙反为仙卷，学气反为气病。 这一篇实际上是在为整套「渐门五步」立规矩、划边界——接下来讲的斋戒、安处、存想、坐忘、神解，都会遵循「易简」这个原则，不涉奇诡，都可以老老实实一步步做到。</p><h3 id="渐门三-·-导读" tabindex="-1">渐门三 · 导读 <a class="header-anchor" href="#渐门三-·-导读" aria-label="Permalink to &quot;渐门三 · 导读&quot;">​</a></h3><p>这是全书结构上最重要的一篇——它正式把整套修行体系的「框架」搭起来。前面两篇讲「为什么」与「用什么原则」，这一篇讲「具体分几步走」。若把全书比作一栋建筑：【神仙】篇打地基（世界观：神仙亦人也），【易简】篇定规矩（方法论：不繁不怪、老实践行），【渐门】篇搭骨架（结构图：五步进阶的完整框架），后面五篇添砖瓦。</p><p><strong>逐句</strong></p><ul><li><p><strong>「易有渐卦，道有渐门。」</strong> 开篇点出这套体系的来源与命名依据：《易经》里有「渐卦」，修道也应有「渐门」。《序卦》云「物不可以终止，故受之以渐」——渐卦讲的是事物发展不能一蹴而就，需循序渐进、按部就班。天隐子借卦名卦义为自己的体系命名。这也可见此书虽讲道教修炼，思维与论证逻辑却与《易》一脉相承——序文说它「契于伯阳」，其实也深植于《易》的思想土壤。</p></li><li><p><strong>「人之修真达性，不能顿悟，必须渐而进之，安而行之，故设渐门，观我所入，则道可见矣。」</strong> 解释为何设「渐门」而不主「顿悟」：人要修得真性、达于通透，不能靠顿悟一步跳达；必须一步步推进、安稳踏实地实行；所以设这套体系。观自己走到哪一步、进到什么程度，「道」就看得见了。这一句回应了那个古老的路线争议——顿悟与渐修（禅宗南宗主顿悟、北宗主渐修，最为著名）；天隐子明确站在渐修这一边。</p></li><li><p><strong>「渐有五门：一曰斋戒，二曰安处，三曰存想，四曰坐忘，五曰神解。」</strong> 全书最重要的一句「目录索引」，正式列出五步的名称与顺序。</p></li><li><p><strong>五个「何谓……曰……」的四字定义</strong></p><ul><li>斋戒＝澡身虚心：「澡身」洗涤身体、调理形骸，「虚心」使心虚静、不杂不满；</li><li>安处＝深居静室：择一个安静、合于阴阳的居处环境；</li><li>存想＝收心复性：把散逸在外的心收回来，恢复本来的天性；</li><li>坐忘＝遗形忘我：忘掉形体的存在，忘掉「我」这个执念；</li><li>神解＝万法通神：一切方法与道理都能贯通、契入于「神」。</li></ul></li><li><p><strong>「是故习此渐门者，了一则渐次至二，了二则渐次至三，了三则渐次至四，了四则渐次至五，神仙成矣。」</strong> 再次强调「渐」的精神：前一步「了」——完成、了当——了，才能进到下一步。这里的「了」不是「做了一下」，而是真正落实、扎实完成，不是浮皮潦草地走个过场。</p></li></ul><p><strong>五步的内在次序</strong></p><p>这个编排有内在逻辑：从外到内、从身到心、从有为到无为。斋戒、安处处理身体与外在环境（「形」的层面）；存想开始转向内心（「心」的层面，但仍「有为」地去存、去想）；坐忘是在存想的基础上，把「存想」的用心本身也放下（由有为入无为）；神解则是前四者水到渠成、自然贯通之后的圆满。</p><p>五个定义本身也呈现出越来越内收、越来越接近无形的走向：澡身虚心（还有具体的身体动作）→ 深居静室（还有具体的外在空间）→ 收心复性（已完全转向内心活动）→ 遗形忘我（连「身体」「自我」这个概念本身都要放下）→ 万法通神（已无法用具体动作或对象来描述）。这一走向，与<a href="/Dao/yijing/shi-yi/wen-yan-zhuan">《坤·文言》</a>「敬以直内，义以方外」及<a href="/Dao/daoism/daoist-classics/zuowang-lun/">《坐忘论》</a>一类道教文献常讲的「由外而内、由粗而精、由有为而无为」是一致的。</p><p><strong>多想一层</strong></p><ul><li><strong>「渐」与「顿」未必是绝对对立的两条路。</strong> 即便禅宗讲顿悟，「悟」之前往往也需要漫长的积累、参悟乃至困顿。所谓「悟」是临界点上的突然贯通，支撑那个贯通的，往往还是长期渐进的积累。天隐子说「不能顿悟」，更准确的理解或许是——不能指望不下功夫、不经历过程就凭空跳到终点；渐修恰恰是让「悟」有根基可依的必要过程。</li><li><strong>「了一则渐次至二」提示不要急着跳步。</strong> 我们常习惯「抓重点」——一看到「存想」「坐忘」这些听起来更高妙的概念，就想跳过前面看似朴素的「斋戒」「安处」。但天隐子说得很清楚：前一步没有真正「了」，很难稳固地进入下一步。这与《易》里「屯见而不失其居」「潜龙勿用」是同一个道理——基础没扎稳，急着往上走，反而容易根基不稳。</li><li><strong>「神解」不是另外学一门新东西。</strong> 从五步的定义顺序也能看出：「神解」没有像前四者那样有具体的动作性定义，而是「万法通神」这样相对抽象、总括性的说法。它是前四门真正贯通之后自然呈现的圆满状态——与第八篇「信、定、闲、慧四门通神，谓之神解」完全一致：神解＝前四者的贯通，而不是外加的第五样东西。</li></ul><p><strong>小结</strong></p><p>易有渐卦 → 道有渐门（来源与命名依据）→ 修真不能顿悟，须渐而进之、安而行之（立场：渐修而非顿悟）→ 渐门五步：斋戒 → 安处 → 存想 → 坐忘 → 神解 → 各自定义：澡身虚心（调身）／深居静室（调境）／收心复性（调心，开始转内）／遗形忘我（更深的转内，放下「存想」本身）／万法通神（前四者贯通后的圆满）→ 每一步须「了」才能进至下一步，不可跳步、不可浮躁。 这一篇搭好了全书最重要的骨架，后面五篇依次把五门逐一展开细讲。</p><h3 id="斋戒四-·-导读" tabindex="-1">斋戒四 · 导读 <a class="header-anchor" href="#斋戒四-·-导读" aria-label="Permalink to &quot;斋戒四 · 导读&quot;">​</a></h3><p>渐门五步的第一步，也是整套修行真正落地实操的第一篇。天隐子在这里讲得非常具体、非常「接地气」，几乎没有玄奥的道理，全是可以直接照做的生活细节。</p><p>【渐门】篇给出的定义是「斋戒者，澡身虚心」，这一篇就是把「澡身虚心」展开。但天隐子开篇先做「排除法」，把对「斋戒」的常见误解划掉，然后才给出自己的定义——先破后立：先破「斋戒＝单纯吃素、澡身＝单纯洗澡去垢」，再立「核心在节食调中（调内）与摩擦畅外（调外）」。</p><p><strong>逐句</strong></p><ul><li><p><strong>「斋戒者，非蔬茹饮食而已；澡身者，非汤浴去垢而已。盖其法在乎节食调中，摩擦畅外者也。」</strong> 全篇总纲，也是对「斋戒」二字的重新定义。很多人一听「斋戒」就以为是吃素，一听「澡身」就以为是热水洗澡去垢——天隐子说，都不止如此。真正的方法在于「节食调中」（节制饮食、调理体内）与「摩擦畅外」（摩擦皮肤、疏畅体外）。这一句纠正的，正是把「斋戒」等同于「戒荤食素」这类表面形式、却忽略其真正目的的误解。</p></li><li><p><strong>「夫人禀五行之气，而食五行之物，实自胞胎有形，已呼吸精血，岂可去食而求长生？」</strong> 讲一个很朴素的道理：人禀受五行之气而生，所食也同是五行之气的产物；自胞胎中有了形体那一刻起，就已在呼吸、依靠精血维持生命——怎么可能靠完全不吃东西来求长生？这是在为后面批判「辟谷断食求仙」之类的极端做法做铺垫。</p></li><li><p><strong>「但世人不知休粮服气，是道家之权宜，非永绝食粒之谓也。」</strong> 点出当时（并延续到后世）修炼圈常见的误解——「休粮服气」（辟谷、断食、只靠服气维生）。天隐子给出很清醒的判断：这只是道家<strong>特殊场合下的权宜之计</strong>，不是要永远断绝谷食。这直接批驳了把辟谷断食当作修行常规的做法，也再次印证【易简】篇「苟言涉奇诡……此非吾学也」的立场。</p></li><li><p><strong>「故食之有斋戒者，斋乃洁净之务，戒乃节约之称。」</strong> 正式给「斋」「戒」二字分别下定义：「斋」讲洁净之事（食物洁净、身体洁净），「戒」讲节制、节约之事。合起来，「斋戒」＝洁净 ＋ 节制，而不是简单粗暴地「不吃这个不吃那个」或彻底断食。</p></li><li><p><strong>「有饥即食，食勿令饱，此所谓调中也。」</strong> 给出具体操作：饿了就吃，不故意忍饿、也不预防性地大吃；吃的时候不要吃到很饱、吃撑。极朴素、极好操作——顺着身体的自然节律去吃，每次留有余地。这也呼应【易简】的精神：真正的养生之道，不需要复杂的饮食理论、不必计算卡路里、不必严格时刻表，只需顺着身体节律，并在「饱」上稍微收着一点。</p></li><li><p><strong>「百味未成熟勿食，五味太多勿食，腐败闭气之物勿食，此皆宜戒也。」</strong> 三条具体的饮食禁忌，都属于「戒」：未成熟（未煮熟）之物不食——易伤脾胃；味道过于浓烈、调味过重者不多食——易扰乱身体平衡；腐败变质或易致胸闷气滞之物不食。三条都极朴素、符合常识，不是玄妙的道家秘法。</p></li><li><p><strong>「手常摩擦皮肤，温热熨去冷气，此所谓畅外也。」</strong> 回应前面「摩擦畅外」：用手经常摩擦皮肤，使身体产生温热，以此驱散体表寒气。类似今天的搓手、摩擦生热、按摩促进血液循环——简单、随时可做。</p></li><li><p><strong>「久坐、久立、久劳、久役，皆宜戒也。」</strong> 再列四条「戒」：长时间坐着、站着、劳作、被役使操劳，都要节制避免。任何一种姿态或活动持续太久，都会损伤身体，需要节制、变换、适时休息。</p></li><li><p><strong>「此是调理形骸之法，形坚则气全，是以斋戒为渐门之首矣。」</strong> 全篇总结，也点出「斋戒」为何排在第一：以上这些（饮食节制＋摩擦畅外＋避免久坐久立久劳久役）都是调理形骸之法；<strong>形坚则气全</strong>；所以斋戒为渐门之首。这条「形坚则气全」的逻辑，也解释了修行为何要从调理身体开始，而不是一上来就讲存想、坐忘这类心念功夫。</p></li></ul><p><strong>多想一层</strong></p><ul><li><strong>「斋戒」不是苦修，而是「恰到好处的节制」。</strong> 全篇没有苦行僧式的自我折磨，反复强调的都是「勿令饱」「久坐久立久劳久役皆宜戒」——重点从来不是「要吃得很少」「要极度克制」，而是「不要过度」。这与《易》里「过」与「中」的辩证是一回事：不走向任何极端（暴食或绝食、劳碌或懒散），而是找到「中」的位置并守住它。</li><li><strong>「形坚则气全」揭示了身心关系的一个逻辑起点。</strong> 把斋戒放在第一步，本身就蕴含一个朴素而重要的智慧：身体是心念修行的载体与基础，身体状态不稳固，心念的功夫就立不住。很多人想提升专注力、想在工作学习中保持清明的头脑，却忽略了最基础的——吃得是否规律而不过量？是否长期久坐不动？是否让身体长期处于紧绷疲惫？这些看似「低阶」「基础」的身体调理，恰恰是一切「高阶」心念功夫的地基。</li><li><strong>批判「休粮服气」的态度，体现一贯的「反奇诡」立场。</strong> 这一篇专门用一段批判「休粮服气」，再次呼应【易简】篇的划界。天隐子始终保持着清醒、务实、不故弄玄虚的态度——即便在讲具体方法时，也不忘先扫清那些容易让人「执迷」「走偏」的极端说法。这也是此书虽篇幅短小，却被评为「实乃修真之枢要」的原因之一：它讲的东西经得起常识的检验，不靠玄乎其辞唬人。</li></ul><p><strong>小结</strong></p><p>先破误解——斋戒 ≠ 单纯吃素，澡身 ≠ 单纯洗澡去垢 → 立定义——斋＝洁净，戒＝节约（节食调中 ＋ 摩擦畅外）→ 批判极端——休粮服气只是权宜之计，不可当作永久之法 → 具体操作：调中（饥即食，食勿令饱）、戒食（未熟勿食、太浓勿食、腐败勿食）、畅外（常摩擦皮肤、温热驱寒）、戒姿（久坐久立久劳久役皆宜戒）→ 总结依据：形坚则气全，故斋戒为渐门之首。 这一篇最见其朴素与克制——没有任何玄妙的说辞，全是关于吃饭、坐立、劳作这些日用之事的提醒。而正是这份朴素，恰恰印证了【易简】篇的道理：真正扎实的修行，往往就藏在这些看似不起眼、却又最容易被忽略的日常习惯里。</p><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/">《坐忘论》</a> —— 与本书互为表里：七阶次第（敬信 → 断缘 → 收心 → 简事 → 真观 → 泰定 → 得道）可视为对「渐门五阶」的详细阐发</li><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/guide">《坐忘论·全书引读》</a> —— 含两书逐篇对应表与关键概念的深化说明</li><li><a href="/Dao/daoism/zhuang-zi/chapter-06">《庄子·大宗师》</a> —— 「坐忘」一词的出处：「堕肢体，黜聪明，离形去知，同于大通」</li></ul><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li>《天隐子》，唐·司马承祯序并后序口诀。</li><li>历代跋语：宋·胡琏跋、王伦书、唐岩起题、明·宋濂辩。</li><li>道藏太玄部收录版本。</li></ul>',59))])}}});export{z as __pageData,c as default};
